import { useMemo } from 'react'
import { type ControllerRenderProps, useFormContext } from 'react-hook-form'
import { Combobox, type ComboboxProps } from '@/registry/new-york/ui/combobox/components/combobox'
import {
  defaultValuePerOperation,
  operationsPerType,
  type SmartFilterFormInput,
  type SmartFilterFormOutput
} from './lib'
import { useSmartFilterContext } from './smart-filter'

// Component
const AdvancedFilterNameField = ({
  index,
  field,
  formFiltersWatcher
}: {
  index: number
  field: ControllerRenderProps<SmartFilterFormInput, `filters.${number}.name`>
  formFiltersWatcher: SmartFilterFormInput['filters']
}) => {
  // Hooks
  const { filters } = useSmartFilterContext()
  const form = useFormContext<SmartFilterFormInput, unknown, SmartFilterFormOutput>()

  // Methods
  const changeValue: ComboboxProps['onValueChange'] = (value) => {
    if (!value) {
      return
    }

    const selectedFilter = filters.find((filter) => filter.name === value)
    if (!selectedFilter) {
      return
    }

    const operation = operationsPerType[selectedFilter.type][0]
    form.setValue(`filters.${index}.type`, selectedFilter.type)
    form.setValue(`filters.${index}.operation`, operation)
    form.setValue(`filters.${index}.value`, defaultValuePerOperation[operation])

    field.onChange(value)
  }

  // Memos
  const options = useMemo<ComboboxProps['options']>(() => {
    const selectedFilters = formFiltersWatcher.map((field) => field.name)
    return filters
      .filter((filter) => filter.name === field.value || !selectedFilters.includes(filter.name))
      .map((filter) => ({
        value: filter.name,
        label: filter.label
      }))
  }, [filters, formFiltersWatcher, field.value])

  // Template
  return <Combobox isCanRemoveValue={false} onValueChange={changeValue} options={options} value={field.value} />
}

export default AdvancedFilterNameField

import { useMemo } from 'react'
import { type ControllerRenderProps, useFormContext, useWatch } from 'react-hook-form'
import { Combobox, type ComboboxProps } from '@/registry/new-york/ui/combobox/components/combobox'
import {
  defaultValuePerOperation,
  operationsPerType,
  type SmartFilterFormInput,
  type SmartFilterFormOutput,
  type SmartFilterOperation,
  SmartFilterType
} from './lib'
import { useSmartFilterContext } from './smart-filter'

const operationLabels: Record<string, Record<string, string | undefined> | undefined> = {
  base: {
    equalsTo: 'Equals to',
    doesNotEqualTo: 'Does not equal to',
    contains: 'Contains',
    isBetween: 'Is between',
    hasAnyOf: 'Has any of',
    hasAllOf: 'Has all of'
  },
  [SmartFilterType.Number]: {
    isLessThan: 'Is less than',
    isLessThanOrEqualTo: 'Is less than or equal to',
    isGreaterThan: 'Is greater than',
    isGreaterThanOrEqualTo: 'Is greater than or equal to'
  },
  [SmartFilterType.Date]: {
    isLessThan: 'Is before',
    isLessThanOrEqualTo: 'Is before or equal to',
    isGreaterThan: 'Is after',
    isGreaterThanOrEqualTo: 'Is after or equal to'
  }
}

// Component
const AdvancedFilterOperationField = ({
  index,
  field
}: {
  index: number
  field: ControllerRenderProps<SmartFilterFormInput, `filters.${number}.operation`>
}) => {
  // Hooks
  const { filters } = useSmartFilterContext()
  const form = useFormContext<SmartFilterFormInput, unknown, SmartFilterFormOutput>()
  const formFilterName = useWatch({
    name: `filters.${index}.name`,
    control: form.control
  })

  // Methods
  const changeValue: ComboboxProps['onValueChange'] = (value) => {
    if (!value) {
      return
    }
    form.setValue(`filters.${index}.value`, defaultValuePerOperation[value as SmartFilterOperation])
    field.onChange(value)
  }

  // Memos
  const options = useMemo<ComboboxProps['options']>(() => {
    const type = filters.find((filter) => filter.name === formFilterName)?.type
    return type
      ? operationsPerType[type].map((operation) => ({
          value: operation,
          label: operationLabels[type]?.[operation] ?? operationLabels.base?.[operation] ?? ''
        }))
      : []
  }, [filters, formFilterName])

  // Template
  return <Combobox isCanRemoveValue={false} onValueChange={changeValue} options={options} value={field.value} />
}

export default AdvancedFilterOperationField

import { toDate } from 'date-fns'
import { MinusIcon } from 'lucide-react'
import { useMemo } from 'react'
import { Controller, useFormContext, useWatch } from 'react-hook-form'
import { MultiSelect } from '@/registry/new-york/molecules/multi-select/components/multi-select'
import { NumberInput } from '@/registry/new-york/molecules/number-input/components/number-input'
import { Combobox } from '@/registry/new-york/ui/combobox/components/combobox'
import { DatePicker, DateRangePicker } from '@/registry/new-york/ui/date-picker/components/date-picker'
import { Field, FieldError } from '@/registry/new-york/ui/field/components/field'
import { Input } from '@/registry/new-york/ui/input/components/input'
import { type SmartFilterFormInput, type SmartFilterFormOutput, SmartFilterOperation, SmartFilterType } from './lib'
import { useSmartFilterContext } from './smart-filter'

// Component
const AdvancedFilterValueField = ({ index }: { index: number }) => {
  // Hooks
  const { filters } = useSmartFilterContext()
  const form = useFormContext<SmartFilterFormInput, unknown, SmartFilterFormOutput>()
  const [formFilterName, formFilterOperation] = useWatch({
    name: [`filters.${index}.name`, `filters.${index}.operation`],
    control: form.control
  })

  // Memos
  // Selected filter
  const selectedFilter = useMemo(() => {
    return filters.find((filter) => filter.name === formFilterName)
  }, [filters, formFilterName])

  // Template
  if (!selectedFilter) {
    return null
  }

  switch (selectedFilter.type) {
    // Number
    case SmartFilterType.Number: {
      // Is between
      if (formFilterOperation === SmartFilterOperation.IsBetween) {
        const valueAdditionalWatcher = form.watch(`filters.${index}.value.additional`)

        return (
          <div className='flex items-center gap-4'>
            <Controller
              control={form.control}
              name={`filters.${index}.value.additional.from`}
              render={({ field, fieldState }) => (
                <Field data-invalid={fieldState.invalid}>
                  <NumberInput
                    onFieldChange={field.onChange}
                    onValueChange={(event) => {
                      field.onChange(event.value)
                      if (+valueAdditionalWatcher.to < +event.value) {
                        form.setValue(`filters.${index}.value.additional.to`, event.value)
                      }
                    }}
                    placeholder={`Enter from ${selectedFilter.label.toLowerCase()}`}
                    value={field.value}
                  />
                  {fieldState.invalid && <FieldError errors={[fieldState.error]} />}
                </Field>
              )}
            />

            <MinusIcon className='size-4 text-muted-foreground' />

            <Controller
              control={form.control}
              name={`filters.${index}.value.additional.to`}
              render={({ field, fieldState }) => (
                <Field data-invalid={fieldState.invalid}>
                  <NumberInput
                    min={valueAdditionalWatcher.from}
                    onFieldChange={field.onChange}
                    onValueChange={(event) => field.onChange(event.value)}
                    placeholder={`Enter to ${selectedFilter.label.toLowerCase()}`}
                    value={field.value}
                  />
                  {fieldState.invalid && <FieldError errors={[fieldState.error]} />}
                </Field>
              )}
            />
          </div>
        )
      }

      // Others else
      return (
        <Controller
          control={form.control}
          name={`filters.${index}.value.default`}
          render={({ field, fieldState }) => (
            <Field data-invalid={fieldState.invalid}>
              <NumberInput
                onFieldChange={field.onChange}
                onValueChange={(event) => field.onChange(event.value)}
                placeholder={`Enter ${selectedFilter.label.toLowerCase()}`}
                value={field.value as string}
              />
              {fieldState.invalid && <FieldError errors={[fieldState.error]} />}
            </Field>
          )}
        />
      )
    }

    // Date
    case SmartFilterType.Date: {
      if (formFilterOperation === SmartFilterOperation.IsBetween) {
        return (
          <Controller
            control={form.control}
            name={`filters.${index}.value.additional`}
            render={({ field, fieldState }) => (
              <Field data-invalid={fieldState.invalid}>
                <DateRangePicker
                  onValueChange={(value) => {
                    field.onChange({
                      from: value?.from?.toISOString() ?? '',
                      to: value?.to?.toISOString() ?? ''
                    })
                  }}
                  placeholder={`Select ${selectedFilter.label.toLowerCase()} range`}
                  value={{
                    from: field.value.from ? new Date(field.value.from) : undefined,
                    to: field.value.to ? new Date(field.value.to) : undefined
                  }}
                />
                {fieldState.invalid && <FieldError errors={[fieldState.error]} />}
              </Field>
            )}
          />
        )
      }

      return (
        <Controller
          control={form.control}
          name={`filters.${index}.value.default`}
          render={({ field, fieldState }) => (
            <Field data-invalid={fieldState.invalid}>
              <DatePicker
                onValueChange={(value) => {
                  field.onChange(value?.toISOString() ?? '')
                }}
                placeholder={`Select ${selectedFilter.label.toLowerCase()}`}
                value={field.value ? toDate(field.value as string) : null}
              />
              {fieldState.invalid && <FieldError errors={[fieldState.error]} />}
            </Field>
          )}
        />
      )
    }

    // Select
    case SmartFilterType.Select: {
      if (formFilterOperation === SmartFilterOperation.HasAnyOf) {
        return (
          <Controller
            control={form.control}
            name={`filters.${index}.value.default`}
            render={({ field, fieldState }) => (
              <Field data-invalid={fieldState.invalid}>
                <MultiSelect
                  buttonTriggerProps={{
                    isLoading: !selectedFilter.options
                  }}
                  onValueChange={field.onChange}
                  options={selectedFilter.options ?? []}
                  placeholder={`Select ${selectedFilter.label.toLowerCase()}`}
                  value={field.value as string[]}
                />
                {fieldState.invalid && <FieldError errors={[fieldState.error]} />}
              </Field>
            )}
          />
        )
      }

      return (
        <Controller
          control={form.control}
          name={`filters.${index}.value.default`}
          render={({ field, fieldState }) => (
            <Field data-invalid={fieldState.invalid}>
              <Combobox
                buttonTriggerProps={{
                  isLoading: !selectedFilter.options
                }}
                onValueChange={(value) => {
                  field.onChange(value ?? '')
                }}
                options={selectedFilter.options ?? []}
                placeholder={`Select ${selectedFilter.label.toLowerCase()}`}
                value={field.value as string}
              />
              {fieldState.invalid && <FieldError errors={[fieldState.error]} />}
            </Field>
          )}
        />
      )
    }

    // Select with infinite query
    case SmartFilterType.SelectWithInfiniteQuery: {
      return null
    }

    // Multi select
    case SmartFilterType.MultiSelect: {
      return (
        <Controller
          control={form.control}
          name={`filters.${index}.value.default`}
          render={({ field, fieldState }) => (
            <Field data-invalid={fieldState.invalid}>
              <MultiSelect
                buttonTriggerProps={{
                  isLoading: !selectedFilter.options
                }}
                onValueChange={field.onChange}
                options={selectedFilter.options ?? []}
                placeholder={`Select ${selectedFilter.label.toLowerCase()}`}
                value={field.value as string[]}
              />
              {fieldState.invalid && <FieldError errors={[fieldState.error]} />}
            </Field>
          )}
        />
      )
    }

    // Default
    default: {
      return (
        <Controller
          control={form.control}
          name={`filters.${index}.value.default`}
          render={({ field, fieldState }) => (
            <Field data-invalid={fieldState.invalid}>
              <Input
                aria-invalid={fieldState.invalid}
                placeholder={`Enter ${selectedFilter.label.toLowerCase()}`}
                {...field}
              />
              {fieldState.invalid && <FieldError errors={[fieldState.error]} />}
            </Field>
          )}
        />
      )
    }
  }
}

export default AdvancedFilterValueField

import { CircleCheckBigIcon, ListFilterIcon, PlusIcon, RefreshCwIcon, TrashIcon } from 'lucide-react'
import { useState } from 'react'
import { Controller, type UseFieldArrayReturn, useFormContext, useWatch } from 'react-hook-form'
import { Badge } from '@/registry/new-york/ui/badge/components/badge'
import { Button } from '@/registry/new-york/ui/button/components/button'
import { Field, FieldError } from '@/registry/new-york/ui/field/components/field'
import { Popover, PopoverContent, PopoverTrigger } from '@/registry/new-york/ui/popover/components/popover'
import AdvancedFilterNameField from './advanced-filter-name-field'
import AdvancedFilterOperationField from './advanced-filter-operation-field'
import AdvancedFilterValueField from './advanced-filter-value-field'
import { defaultSmartFilterFormValue, type Filter, type SmartFilterFormInput, type SmartFilterFormOutput } from './lib'
import { type SmartFilterProps, useSmartFilterContext } from './smart-filter'

// Component
const AdvancedFilter = ({
  formFilters,
  addFilter,
  setFilters
}: Pick<SmartFilterProps, 'setFilters'> & {
  formFilters: UseFieldArrayReturn<SmartFilterFormInput, 'filters'>
  addFilter: (filter: Filter) => void
}) => {
  // Hooks
  const { filters } = useSmartFilterContext()
  const form = useFormContext<SmartFilterFormInput, unknown, SmartFilterFormOutput>()
  const formFiltersWatcher = useWatch({
    control: form.control,
    name: 'filters'
  })

  // States
  const [isOpenPopover, setIsOpenPopover] = useState(false)
  const [totalFilterApplied, setTotalFilterApplied] = useState(form.formState.defaultValues?.filters?.length ?? 0)

  // Methods
  const executeLogicOnOpenPopover = () => {
    if (formFilters.fields.length === 0) {
      addFilter(filters[0])
    }
  }

  const clickAddingButton = () => {
    const selectedFilters = formFiltersWatcher.map((field) => field.name)
    const unSelectFilters = filters.filter((filter) => !selectedFilters.includes(filter.name))
    if (unSelectFilters.length > 0) {
      addFilter(unSelectFilters[0])
    }
  }

  const resetFilter = () => {
    formFilters.remove()
    setTotalFilterApplied(0)
    setFilters(defaultSmartFilterFormValue)
    if (filters.length > 0) {
      addFilter(filters[0])
    }
  }

  const applyFilter = (fieldValues: SmartFilterFormOutput) => {
    setFilters(fieldValues)
    setTotalFilterApplied(fieldValues.filters.length)
    setIsOpenPopover(false)
  }

  // Template
  return (
    <Popover onOpenChange={setIsOpenPopover} open={isOpenPopover}>
      <PopoverTrigger asChild>
        <Button variant='outline'>
          <span>Filters</span>
          <ListFilterIcon />
          {totalFilterApplied > 0 && (
            <Badge className='flex size-5 items-center justify-center rounded-sm p-0 leading-none' variant='secondary'>
              {totalFilterApplied}
            </Badge>
          )}
        </Button>
      </PopoverTrigger>

      <PopoverContent
        align='start'
        className='w-(--radix-popper-available-width) xl:w-auto'
        onOpenAutoFocus={executeLogicOnOpenPopover}
      >
        <h3 className='typography-h3'>Filters</h3>
        <div className='-mx-1 my-2 max-h-72 overflow-y-auto px-1'>
          {/* Filters */}
          {formFilters.fields.map((field, index) => (
            <div className='flex gap-x-4' key={field.id}>
              <div className='flex grow flex-col gap-4 py-2 xl:w-auto xl:flex-row'>
                {/* Name */}
                <Controller
                  control={form.control}
                  name={`filters.${index}.name`}
                  render={({ field, fieldState }) => (
                    <Field className='w-full shrink-0 xl:w-52' data-invalid={fieldState.invalid}>
                      <AdvancedFilterNameField field={field} formFiltersWatcher={formFiltersWatcher} index={index} />
                      {fieldState.invalid && <FieldError errors={[fieldState.error]} />}
                    </Field>
                  )}
                />

                {/* Operation */}
                <Controller
                  control={form.control}
                  name={`filters.${index}.operation`}
                  render={({ field, fieldState }) => (
                    <Field className='w-full shrink-0 xl:w-52' data-invalid={fieldState.invalid}>
                      <AdvancedFilterOperationField field={field} index={index} />
                      {fieldState.invalid && <FieldError errors={[fieldState.error]} />}
                    </Field>
                  )}
                />

                {/* Value */}
                <AdvancedFilterValueField index={index} />
              </div>

              {/* Remove button */}
              {formFilters.fields.length > 1 && (
                <Button
                  className='mt-2 shrink-0'
                  onClick={() => formFilters.remove(index)}
                  size='icon'
                  variant='outline'
                >
                  <TrashIcon className='h-4 w-4' />
                </Button>
              )}
            </div>
          ))}
        </div>

        {/* Actions */}
        <div className='flex items-center justify-end gap-4'>
          {formFilters.fields.length < filters.length && (
            <Button onClick={clickAddingButton} variant='outline'>
              <PlusIcon />
              <span>Add</span>
            </Button>
          )}

          <Button onClick={resetFilter} variant='secondary'>
            <RefreshCwIcon />
            <span>Reset</span>
          </Button>

          <Button onClick={form.handleSubmit(applyFilter)} type='submit'>
            <CircleCheckBigIcon />
            <span>Apply</span>
          </Button>
        </div>
      </PopoverContent>
    </Popover>
  )
}

export default AdvancedFilter

import { useDebounce } from '@uidotdev/usehooks'
import { SearchIcon } from 'lucide-react'
import { useEffect } from 'react'
import { Controller, useFormContext, useWatch } from 'react-hook-form'
import { Field } from '@/registry/new-york/ui/field/components/field'
import { InputGroup, InputGroupAddon, InputGroupInput } from '@/registry/new-york/ui/input-group/components/input-group'
import type { SmartFilterFormInput, SmartFilterFormOutput } from './lib'
import type { SmartFilterProps } from './smart-filter'

// Component
const BasicSearch = ({ setFilters }: Pick<SmartFilterProps, 'setFilters'>) => {
  // Hooks
  const form = useFormContext<SmartFilterFormInput, unknown, SmartFilterFormOutput>()

  const formSearch = useWatch({
    name: 'search',
    control: form.control
  })

  const debouncedFormSearch = useDebounce<string>(formSearch.trim(), 400)

  // Effects
  useEffect(() => {
    setFilters({ search: debouncedFormSearch, filters: [] })
  }, [debouncedFormSearch, setFilters])

  // Template
  return (
    <Controller
      control={form.control}
      name='search'
      render={({ field, fieldState }) => (
        <Field data-invalid={fieldState.invalid}>
          <InputGroup>
            <InputGroupInput {...field} aria-invalid={fieldState.invalid} placeholder='Search' />
            <InputGroupAddon>
              <SearchIcon />
            </InputGroupAddon>
          </InputGroup>
        </Field>
      )}
    />
  )
}

export default BasicSearch

import { zodResolver } from '@hookform/resolvers/zod'
import { useForm } from 'react-hook-form'
import z from 'zod'

export enum SmartFilterLogicalOperation {
  And = ',',
  Or = '|'
}

export enum SmartFilterOperation {
  EqualsTo = 'equalsTo',
  DoesNotEqualTo = 'doesNotEqualTo',
  Contains = 'contains',
  IsLessThan = 'isLessThan',
  IsLessThanOrEqualTo = 'isLessThanOrEqualTo',
  IsGreaterThan = 'isGreaterThan',
  IsGreaterThanOrEqualTo = 'isGreaterThanOrEqualTo',
  IsBetween = 'isBetween',
  HasAnyOf = 'hasAnyOf',
  HasAllOf = 'hasAllOf'
}

export enum SmartFilterType {
  Text = 'text',
  Number = 'number',
  Date = 'date',
  Select = 'select',
  SelectWithInfiniteQuery = 'select-with-infinite-query',
  MultiSelect = 'multi-select'
}

export enum SmartFilterApiOperation {
  Equal = '==',
  NotEqual = '!=',
  LessThan = '<',
  GreaterThan = '>',
  LessThanOrEqual = '<=',
  GreaterThanOrEqual = '>=',
  Contain = '@=',
  StartWith = '_=',
  NotStartWith = '!_=',
  CaseInsensitiveStringContain = '@=*',
  CaseInsensitiveStringNotContain = '!@=*',
  CaseInsensitiveStartWith = '_=*',
  CaseInsensitiveNotStartWith = '!_=*',
  CaseInsensitiveEqual = '==*',
  CaseInsensitiveNotEqual = '!=*',
  EqualArray = '[]'
}

export const operationsPerType: Record<SmartFilterType, SmartFilterOperation[]> = {
  [SmartFilterType.Text]: [
    SmartFilterOperation.EqualsTo,
    SmartFilterOperation.DoesNotEqualTo,
    SmartFilterOperation.Contains
  ],
  [SmartFilterType.Number]: [
    SmartFilterOperation.EqualsTo,
    SmartFilterOperation.DoesNotEqualTo,
    SmartFilterOperation.IsLessThan,
    SmartFilterOperation.IsLessThanOrEqualTo,
    SmartFilterOperation.IsGreaterThan,
    SmartFilterOperation.IsGreaterThanOrEqualTo,
    SmartFilterOperation.IsBetween
  ],
  [SmartFilterType.Date]: [
    SmartFilterOperation.EqualsTo,
    SmartFilterOperation.IsLessThan,
    SmartFilterOperation.IsLessThanOrEqualTo,
    SmartFilterOperation.IsGreaterThan,
    SmartFilterOperation.IsGreaterThanOrEqualTo,
    SmartFilterOperation.IsBetween
  ],
  [SmartFilterType.Select]: [
    SmartFilterOperation.EqualsTo,
    SmartFilterOperation.DoesNotEqualTo,
    SmartFilterOperation.HasAnyOf
  ],
  [SmartFilterType.SelectWithInfiniteQuery]: [
    SmartFilterOperation.EqualsTo,
    SmartFilterOperation.DoesNotEqualTo,
    SmartFilterOperation.HasAnyOf
  ],
  [SmartFilterType.MultiSelect]: [SmartFilterOperation.HasAnyOf, SmartFilterOperation.HasAllOf]
} as const

export const defaultStringValue = {
  default: '',
  additional: {
    from: '',
    to: ''
  }
} as const

export const defaultStringArrayValue = {
  default: '',
  additional: {
    from: '',
    to: ''
  }
} as const

export const defaultValuePerOperation: Record<SmartFilterOperation, SmartFilterFormOutput['filters'][number]['value']> =
  {
    [SmartFilterOperation.EqualsTo]: defaultStringValue,
    [SmartFilterOperation.DoesNotEqualTo]: defaultStringValue,
    [SmartFilterOperation.IsLessThan]: defaultStringValue,
    [SmartFilterOperation.IsLessThanOrEqualTo]: defaultStringValue,
    [SmartFilterOperation.IsGreaterThan]: defaultStringValue,
    [SmartFilterOperation.IsGreaterThanOrEqualTo]: defaultStringValue,
    [SmartFilterOperation.Contains]: defaultStringValue,
    [SmartFilterOperation.IsBetween]: defaultStringValue,
    [SmartFilterOperation.HasAnyOf]: defaultStringArrayValue,
    [SmartFilterOperation.HasAllOf]: defaultStringArrayValue
  } as const

export const apiOperationPerOperation: Partial<Record<SmartFilterOperation, SmartFilterApiOperation>> = {
  [SmartFilterOperation.EqualsTo]: SmartFilterApiOperation.Equal,
  [SmartFilterOperation.DoesNotEqualTo]: SmartFilterApiOperation.NotEqual,
  [SmartFilterOperation.IsLessThan]: SmartFilterApiOperation.LessThan,
  [SmartFilterOperation.IsLessThanOrEqualTo]: SmartFilterApiOperation.LessThanOrEqual,
  [SmartFilterOperation.IsGreaterThan]: SmartFilterApiOperation.GreaterThan,
  [SmartFilterOperation.IsGreaterThanOrEqualTo]: SmartFilterApiOperation.GreaterThanOrEqual,
  [SmartFilterOperation.Contains]: SmartFilterApiOperation.Contain
} as const

export const smartFilterFormSchema = z.object({
  search: z.string().trim(),
  filters: z.array(
    z
      .object({
        name: z.string().trim(),
        operation: z.enum(SmartFilterOperation),
        type: z.enum(SmartFilterType),
        value: z.object({
          default: z.union([z.string().trim(), z.array(z.string()).min(1, 'Please enter/select the information')]),
          additional: z.object({
            from: z.string(),
            to: z.string()
          })
        })
      })
      .superRefine((fieldValues, ctx) => {
        const { value, operation } = fieldValues

        if (operation === SmartFilterOperation.IsBetween) {
          if (value.additional.from === '') {
            const fields = ['value.additional', 'value.additional.from']
            for (const field of fields) {
              ctx.addIssue({
                path: [field],
                message: 'Please enter/select the information',
                code: 'custom'
              })
            }
          }

          if (value.additional.to === '') {
            const fields = ['value.additional', 'value.additional.to']
            for (const field of fields) {
              ctx.addIssue({
                path: [field],
                message: 'Please enter/select the information',
                code: 'custom'
              })
            }
          }
        } else if (value.default === '') {
          ctx.addIssue({
            path: ['value.default'],
            message: 'Please enter/select the information',
            code: 'custom'
          })
        }
      })
  )
})

export const defaultSmartFilterFormValue: SmartFilterFormInput = {
  search: '',
  filters: []
} as const

export interface Filter {
  label: string
  name: string
  type: SmartFilterType
  options?: Array<{
    value: string
    label: string
  }>
  apiPath?: string
  datePickerFormat?: 'date' | 'month' | 'year'
}

export type SmartFilterFormInput = z.input<typeof smartFilterFormSchema>

export type SmartFilterFormOutput = z.output<typeof smartFilterFormSchema>

export const useSmartFilterForm = ({ defaultFormValue }: { defaultFormValue?: SmartFilterFormInput } = {}) => {
  return useForm<SmartFilterFormInput, unknown, SmartFilterFormOutput>({
    resolver: zodResolver(smartFilterFormSchema),
    defaultValues: defaultFormValue ?? defaultSmartFilterFormValue
  })
}

import { ListFilter, Search } from 'lucide-react'
import React from 'react'
import { FormProvider, type SubmitHandler, type UseFormReturn, useFieldArray } from 'react-hook-form'
import { ToggleGroup, ToggleGroupItem } from '@/registry/new-york/ui/toggle-group/components/toggle-group'
import AdvancedFilter from './advanced-filter'
import BasicSearch from './basic-search'
import {
  defaultValuePerOperation,
  type Filter,
  operationsPerType,
  type SmartFilterFormInput,
  type SmartFilterFormOutput
} from './lib'

// Smart filter
enum Mode {
  BasicSearch = 'basic-search',
  AdvancedFilter = 'advanced-filter'
}

export interface SmartFilterContextValue {
  filters: NonNullable<SmartFilterProps['filters']>
}

const SmartFilterContext = React.createContext<SmartFilterContextValue | null>(null)

export const useSmartFilterContext = () => {
  const context = React.useContext(SmartFilterContext)
  if (!context) {
    throw new Error('useFiltersContext should be used within the SmartFilter')
  }
  return context
}

export interface SmartFilterProps {
  form: UseFormReturn<SmartFilterFormInput, unknown, SmartFilterFormOutput>
  filters?: Filter[]
  isHideSearchMode?: boolean
  setFilters: SubmitHandler<SmartFilterFormOutput>
}

const DEFAULT_FILTERS: Filter[] = []

export const SmartFilter = ({
  form,
  filters = DEFAULT_FILTERS,
  isHideSearchMode = false,
  setFilters
}: SmartFilterProps) => {
  // Hooks
  const formFilters = useFieldArray({
    control: form.control,
    name: 'filters'
  })

  // States
  const [mode, setMode] = React.useState<Mode>(() =>
    (form.formState.defaultValues?.filters ?? DEFAULT_FILTERS).length > 0 ? Mode.AdvancedFilter : Mode.BasicSearch
  )

  // Methods
  const addFilter = (filter: Filter) => {
    const { name, type } = filter
    const operation = operationsPerType[type][0]
    formFilters.append({
      name,
      type,
      operation,
      value: defaultValuePerOperation[operation]
    })
  }

  const changeMode = (value: string) => {
    setMode(value as Mode)
    switch (value) {
      case Mode.BasicSearch: {
        formFilters.remove()
        break
      }
      case Mode.AdvancedFilter: {
        form.resetField('search')
        if (filters.length > 0) {
          addFilter(filters[0])
        }
        break
      }
      default: {
        break
      }
    }
  }

  // Template
  if (form.formState.isLoading) {
    return null
  }

  return (
    <SmartFilterContext.Provider
      value={{
        filters
      }}
    >
      <FormProvider {...form}>
        <form className='w-full' onSubmit={(e) => e.preventDefault()}>
          {filters.length === 0 ? (
            <BasicSearch setFilters={setFilters} />
            // biome-ignore lint/style/noNestedTernary: ignore
          ) : isHideSearchMode ? (
            <AdvancedFilter addFilter={addFilter} formFilters={formFilters} setFilters={setFilters} />
          ) : (
            <div className='flex items-center gap-2'>
              <ToggleGroup
                className='data-[variant=outline]:shadow-none'
                onValueChange={changeMode}
                type='single'
                value={mode}
                variant='outline'
              >
                <ToggleGroupItem value={Mode.BasicSearch}>
                  <Search />
                </ToggleGroupItem>

                <ToggleGroupItem value={Mode.AdvancedFilter}>
                  <ListFilter />
                </ToggleGroupItem>
              </ToggleGroup>

              {mode === Mode.BasicSearch ? (
                <BasicSearch setFilters={setFilters} />
              ) : (
                <AdvancedFilter addFilter={addFilter} formFilters={formFilters} setFilters={setFilters} />
              )}
            </div>
          )}
        </form>
      </FormProvider>
    </SmartFilterContext.Provider>
  )
}
